// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address admin;
    function setUp() public {
        admin = address(this);
        c = new Owned();
    }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != admin);
        vm.assume(newOwner != address(0));
        address originalOwner = c.owner();
        bool ok;
        vm.prank(actor);
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        bool ownerChanged = (c.owner() != originalOwner);
        assertTrue(!(ok && ownerChanged));
    }
}
